package main

import (
	"bytes"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	"github.com/mas-bandwidth/schema/v2/compiler"
)

// cookDifferential is THE TOOL AGAINST THE REFERENCE, with nothing pinned in
// between (docs/SPEC-TABLES.md §2.8, §2.9, §7.6). For every `cook-write` row it
// cooks the instance's wire with the tool's engine in this process, in both
// byte orders, and asks the C++ reference driver for its own cook of the same
// wire, and the two must be the same bytes. The committed cook-write files are
// not read: a fixture regenerated by a broken tool cannot stand in for the
// reference here, which is what makes this the gate on the tool's layout of a
// map's entry array and a list's element array in the holder's node extent.
//
// The driver is the reference leg's command (test/conformance/cpp/driver unless
// --driver names another); its `cook-write` surface writes <instance> and
// <instance>-be into the work directory.
func cookDifferential(w io.Writer, m *Manifest, manifest, driverCmd, work string) (bool, error) {
	if driverCmd == "" {
		driverCmd = filepath.ToSlash(filepath.Join(defaultDriversDir, referenceLang, "driver"))
	}
	out := filepath.Join(work, "reference")
	if err := os.RemoveAll(out); err != nil {
		return false, err
	}
	if err := os.MkdirAll(out, 0o755); err != nil {
		return false, err
	}
	d := driver{lang: referenceLang, argv: strings.Fields(driverCmd)}
	code, stderr, err := runDriver(d, manifest, "cook-write", out)
	if err != nil {
		return false, err
	}
	if code != 0 {
		return false, fmt.Errorf("the reference's cook-write surface exited %d — it must answer every row\n%s", code, stderr)
	}

	u := newUnits(m)
	ok, rows := true, 0
	for _, cw := range m.CookWrites {
		inst, err := m.LookupInstance(cw.Instance)
		if err != nil {
			return false, err
		}
		unit, err := u.get(inst.Unit)
		if err != nil {
			return false, err
		}
		wire, err := os.ReadFile(inst.Wire)
		if err != nil {
			return false, fmt.Errorf("%s: %w", cw.Instance, err)
		}
		for _, arm := range []struct {
			name string
			big  bool
		}{{cw.Instance, false}, {cw.Instance + "-be", true}} {
			rows++
			tool, _, _, err := u.c.Cook(unit, inst.Root, wire, compiler.CookOptions{Big: arm.big})
			if err != nil {
				fmt.Fprintf(w, "DIFFERS %s: the tool refused it: %v\n", arm.name, err)
				ok = false
				continue
			}
			ref, err := os.ReadFile(filepath.Join(out, arm.name))
			if err != nil {
				fmt.Fprintf(w, "DIFFERS %s: the reference wrote nothing: %v\n", arm.name, err)
				ok = false
				continue
			}
			if !bytes.Equal(tool, ref) {
				fmt.Fprintf(w, "DIFFERS %s\n", describeDiff(arm.name, ref, tool))
				ok = false
			}
		}
	}
	if ok {
		fmt.Fprintf(w, "cook differential: the tool and the C++ reference agree on %d cooks (%d rows, both byte orders)\n", rows, len(m.CookWrites))
	}
	return ok, nil
}
